import{_ as t,c as d,o,b2 as r}from"./chunks/framework.CUhoHPxN.js";const m=JSON.parse('{"title":"菜单管理设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-14-menu-management-design.md","filePath":"superpowers/specs/2026-05-14-menu-management-design.md"}'),c={name:"superpowers/specs/2026-05-14-menu-management-design.md"};function a(s,e,l,n,i,u){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="菜单管理设计文档" tabindex="-1">菜单管理设计文档 <a class="header-anchor vp-link" href="#菜单管理设计文档" aria-label="Permalink to &quot;菜单管理设计文档&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>在系统管理域内提供「菜单管理」能力：维护目录 / 菜单 / 按钮三类节点的树形数据，作为 <strong>动态路由与权限标识</strong> 的权威来源；并与登录后 <strong><code>GET /getRouters</code></strong> 打通，替换当前后端占位空列表。原始需求见 <code>原始需求/系统管理/菜单管理-需求文档.md</code>。本文档为经 <code>/brainstorming</code> 澄清与方案确认后的<strong>定稿设计</strong>；与原始需求不一致处（尤其 HTTP 方法、删除拦截范围、接口路径子资源）以本文为准。</p><p><strong>架构方案（已确认）</strong>：方案一 — <strong>菜单域单模块内聚</strong>，由 <code>MenuService</code>（及必要的同包 VO 组装辅助）承担管理端树、<code>treeselect</code>、<code>roleMenuTreeselect</code>、CRUD 校验及 <strong>动态路由 VO 构建</strong>；<code>AuthController.getRouters</code> 仅作入口委托。</p><h2 id="_2-需求澄清结论-已确认" tabindex="-1">2. 需求澄清结论（已确认） <a class="header-anchor vp-link" href="#_2-需求澄清结论-已确认" aria-label="Permalink to &quot;2. 需求澄清结论（已确认）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>序号</th><th>结论</th></tr></thead><tbody><tr><td>1</td><td>写操作 HTTP 形态对齐仓库约定：<strong>新增/修改/删除统一 <code>POST</code> 子路径</strong>（不使用 <code>PUT</code>/<code>DELETE</code>），与 <code>SysDeptController</code> / <code>SysConfigController</code> 风格一致；同步修订原始需求 §6 与前端 API。</td></tr><tr><td>2</td><td><strong>同一迭代</strong>打通 <strong><code>GET /getRouters</code></strong>：菜单表（及角色-菜单）为路由与权限的源数据，登录后按用户角色过滤返回若依兼容路由树。</td></tr><tr><td>3</td><td>纳入 <strong><code>GET /system/menu/roleMenuTreeselect/{roleId}</code></strong>；需具备真实 <strong><code>sys_role</code></strong> 与 <strong><code>sys_role_menu</code></strong>（及使当前用户能关联到角色的最小方案，见 §3.2 / §6）。</td></tr><tr><td>4</td><td>删除拦截（本迭代）：<strong>仅</strong>当存在未逻辑删除的<strong>子节点</strong>时拒绝；<strong>不</strong>校验「角色仍引用该菜单」。</td></tr><tr><td>5</td><td>树主键与父级：<strong><code>BIGINT</code> 主键</strong>、<strong><code>parent_id</code> 顶级 = -1</strong>（与 <code>sys_dept</code> 一致）。</td></tr></tbody></table></div><h2 id="_3-范围与非范围" tabindex="-1">3. 范围与非范围 <a class="header-anchor vp-link" href="#_3-范围与非范围" aria-label="Permalink to &quot;3. 范围与非范围&quot;">​</a></h2><h3 id="_3-1-实施范围" tabindex="-1">3.1 实施范围 <a class="header-anchor vp-link" href="#_3-1-实施范围" aria-label="Permalink to &quot;3.1 实施范围&quot;">​</a></h3><ul><li>后端：<code>sys_menu</code>、<code>sys_role</code>、<code>sys_role_menu</code> 的 Flyway 迁移与领域模型；<code>MenuService</code>、<code>SysMenuController</code>；<code>getRouters</code> 委托实现；校验与项目统一异常。</li><li>前端：<code>quick-ui</code> 菜单管理路由与页面、API 模块、树表与表单（按类型显隐）、权限指令与 <code>system:menu:*</code> 对齐。</li><li>种子数据：至少内置角色、菜单管理相关菜单节点、角色-菜单关联，保证可验收列表与 <code>roleMenuTreeselect</code>。</li></ul><h3 id="_3-2-明确不做-本迭代" tabindex="-1">3.2 明确不做（本迭代） <a class="header-anchor vp-link" href="#_3-2-明确不做-本迭代" aria-label="Permalink to &quot;3.2 明确不做（本迭代）&quot;">​</a></h3><ul><li>删除菜单时因 <strong>角色仍引用</strong> 而拦截（可后续变更扩展）。</li><li>完整的「用户管理 / 用户分配角色」界面（若用户表尚无 <code>user_role</code>，可采用 <strong>最小 <code>sys_user_role</code> 或开发期默认绑定策略</strong> 满足 <code>getRouters</code> 验收，见 §6 开放式问题落地后关闭）。</li></ul><h2 id="_4-数据模型" tabindex="-1">4. 数据模型 <a class="header-anchor vp-link" href="#_4-数据模型" aria-label="Permalink to &quot;4. 数据模型&quot;">​</a></h2><h3 id="_4-1-表-sys-menu-字段与-ruoyi-常见模型对齐-实现时可微调类型" tabindex="-1">4.1 表 <code>sys_menu</code>（字段与 RuoYi 常见模型对齐，实现时可微调类型） <a class="header-anchor vp-link" href="#_4-1-表-sys-menu-字段与-ruoyi-常见模型对齐-实现时可微调类型" aria-label="Permalink to &quot;4.1 表 `sys_menu`（字段与 RuoYi 常见模型对齐，实现时可微调类型）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>字段</th><th>类型（建议）</th><th>说明</th></tr></thead><tbody><tr><td><code>menu_id</code></td><td>BIGINT PK</td><td>与现有 <code>sys_*</code> 主键策略一致</td></tr><tr><td><code>parent_id</code></td><td>BIGINT NOT NULL</td><td>顶级 <strong>-1</strong></td></tr><tr><td><code>menu_type</code></td><td>CHAR(1)</td><td><code>M</code> 目录、<code>C</code> 菜单、<code>F</code> 按钮（或项目统一枚举，与前端字典一致）</td></tr><tr><td><code>menu_name</code></td><td>VARCHAR(50)</td><td>显示名称</td></tr><tr><td><code>order_num</code></td><td>INT</td><td>排序</td></tr><tr><td><code>path</code></td><td>VARCHAR(200)</td><td>路由地址</td></tr><tr><td><code>component</code></td><td>VARCHAR(255)</td><td>组件路径，目录/按钮可空</td></tr><tr><td><code>query</code></td><td>VARCHAR(255)</td><td>可选，路由 query</td></tr><tr><td><code>perms</code></td><td>VARCHAR(100)</td><td>权限标识</td></tr><tr><td><code>icon</code></td><td>VARCHAR(100)</td><td>图标</td></tr><tr><td><code>visible</code></td><td>CHAR(1)</td><td>是否显示（如 0 显示 1 隐藏）</td></tr><tr><td><code>status</code></td><td>CHAR(1)</td><td>与 <strong><code>sys_normal_disable</code></strong> 或项目统一状态字典一致</td></tr><tr><td><code>is_frame</code></td><td>CHAR(1)</td><td>是否外链</td></tr><tr><td><code>is_cache</code></td><td>CHAR(1)</td><td>是否缓存 keep-alive</td></tr><tr><td><code>remark</code></td><td>VARCHAR(500)</td><td>可选</td></tr><tr><td><code>del_flag</code></td><td>CHAR(1)</td><td>逻辑删除，与部门表语义一致</td></tr><tr><td>审计字段</td><td>create_by / create_time / update_by / update_time</td><td>与项目约定一致</td></tr></tbody></table></div><p>索引建议：<code>(parent_id, del_flag)</code>；按需 <code>(status, del_flag)</code>。</p><h3 id="_4-2-表-sys-role-最小" tabindex="-1">4.2 表 <code>sys_role</code>（最小） <a class="header-anchor vp-link" href="#_4-2-表-sys-role-最小" aria-label="Permalink to &quot;4.2 表 `sys_role`（最小）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>role_id</code></td><td>BIGINT PK</td></tr><tr><td><code>role_name</code>、<code>role_key</code></td><td>展示与唯一键</td></tr><tr><td><code>status</code>、<code>del_flag</code>、排序、备注、审计字段</td><td>与项目惯例一致</td></tr></tbody></table></div><h3 id="_4-3-表-sys-role-menu" tabindex="-1">4.3 表 <code>sys_role_menu</code> <a class="header-anchor vp-link" href="#_4-3-表-sys-role-menu" aria-label="Permalink to &quot;4.3 表 `sys_role_menu`&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>role_id</code>、<code>menu_id</code></td><td>联合主键或唯一约束</td></tr></tbody></table></div><h2 id="_5-接口契约" tabindex="-1">5. 接口契约 <a class="header-anchor vp-link" href="#_5-接口契约" aria-label="Permalink to &quot;5. 接口契约&quot;">​</a></h2><p>统一响应 <strong><code>R</code></strong>。下列路径为能力说明；<strong>具体 POST 子路径</strong>（<code>/create</code>、<code>/update</code>、<code>/remove</code> 或 <code>/remove/{id}</code>）在实现阶段与 <code>tasks.md</code> 对齐现有 <code>SysConfigController</code> / <code>SysDeptController</code> 风格并保持全仓一致。</p><div class="vp-table"><table><thead><tr><th>能力</th><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>树形列表</td><td>GET</td><td><code>/system/menu/list</code></td><td>Query：菜单名称（模糊）、状态（精确）；<strong>成功 <code>data</code> 为嵌套树根数组</strong>，<code>children</code> 无子为空数组</td></tr><tr><td>详情</td><td>GET</td><td><code>/system/menu/{menuId}</code></td><td>编辑回显</td></tr><tr><td>下拉树</td><td>GET</td><td><code>/system/menu/treeselect</code></td><td>全量树，<code>id</code>/<code>label</code>/<code>children</code>，<strong>忽略</strong>列表筛选条件</td></tr><tr><td>角色菜单树</td><td>GET</td><td><code>/system/menu/roleMenuTreeselect/{roleId}</code></td><td>全量树 + 已勾选 menuId 列表（字段名与前端联调确定）</td></tr><tr><td>新增</td><td>POST</td><td><code>/system/menu</code> 或 <code>/system/menu/create</code></td><td>Body 校验；类型与字段组合见 §6</td></tr><tr><td>修改</td><td>POST</td><td><code>/system/menu/update</code></td><td>Body 含 <code>menuId</code></td></tr><tr><td>删除</td><td>POST</td><td><code>/system/menu/remove</code> 等</td><td>有未删子节点则失败</td></tr><tr><td>动态路由</td><td>GET</td><td><code>/getRouters</code></td><td>已登录；<code>data</code> 为前端 <code>filterAsyncRouter</code> 兼容的路由数组</td></tr></tbody></table></div><p><strong>与原始需求文档 §6 的差异</strong>：不以 <code>PUT</code>/<code>DELETE</code> 暴露修改与删除；<code>roleMenuTreeselect</code> 路径保持 REST 风格子资源。</p><h2 id="_6-后端设计" tabindex="-1">6. 后端设计 <a class="header-anchor vp-link" href="#_6-后端设计" aria-label="Permalink to &quot;6. 后端设计&quot;">​</a></h2><h3 id="_6-1-分层与包结构" tabindex="-1">6.1 分层与包结构 <a class="header-anchor vp-link" href="#_6-1-分层与包结构" aria-label="Permalink to &quot;6.1 分层与包结构&quot;">​</a></h3><ul><li>包路径：<code>io.github.genkidoudou.web.system.menu</code>（与 <code>dept</code>、<code>config</code> 并列）。</li><li>分层：<code>controller</code> / <code>service</code> / <code>service.impl</code> / <code>mapper</code> / <code>domain</code> / <code>dto</code>（SaveRequest、Query、Vo、TreeSelectVo 等）。</li></ul><h3 id="_6-2-树与筛选" tabindex="-1">6.2 树与筛选 <a class="header-anchor vp-link" href="#_6-2-树与筛选" aria-label="Permalink to &quot;6.2 树与筛选&quot;">​</a></h3><ul><li>实现策略参考 <strong><code>DeptServiceImpl</code></strong>：加载未删全量 → 内存建树；有筛选时计算保留节点 id 集合并剪枝保留祖先链。</li><li><strong><code>treeselect</code></strong> 始终全量，不受列表 query 影响。</li></ul><h3 id="_6-3-校验规则" tabindex="-1">6.3 校验规则 <a class="header-anchor vp-link" href="#_6-3-校验规则" aria-label="Permalink to &quot;6.3 校验规则&quot;">​</a></h3><ul><li>父节点存在且未删除；<code>parent_id = -1</code> 表示顶级。</li><li>禁止父级为自身；修改父级时 <strong>防环</strong>（父级不得落在当前节点及其子孙 id 集合内）。</li><li><strong>按 <code>menu_type</code> 显隐/必填</strong>：例如按钮不要求 <code>component</code>/路由等（与需求 §4 一致）。</li><li>删除：<strong>仅</strong>子节点存在则拒绝；返回明确 <strong><code>msg</code></strong>（<code>WarningException</code> 或项目等价物）。</li></ul><h3 id="_6-4-getrouters-与-vo" tabindex="-1">6.4 <code>getRouters</code> 与 VO <a class="header-anchor vp-link" href="#_6-4-getrouters-与-vo" aria-label="Permalink to &quot;6.4 `getRouters` 与 VO&quot;">​</a></h3><ul><li>从 <strong>当前用户 → 角色 → sys_role_menu → sys_menu</strong> 得到可见菜单树；过滤停用、隐藏策略与若依语义对齐（隐藏目录是否仍参与路由由实现注释说明）。</li><li>输出字段需包含前端已有逻辑依赖项：<code>path</code>、<code>name</code>（若需）、<code>component</code>、<code>redirect</code>、<code>meta</code>（<code>title</code>、<code>icon</code>、<code>noCache</code> 等）、<code>children</code>、<code>hidden</code> 等；<strong>与 <code>quick-ui/src/store/modules/permission.js</code> 中 <code>filterAsyncRouter</code> 对齐</strong>，必要时单测或联调截图固化。</li></ul><h3 id="_6-5-权限与会话" tabindex="-1">6.5 权限与会话 <a class="header-anchor vp-link" href="#_6-5-权限与会话" aria-label="Permalink to &quot;6.5 权限与会话&quot;">​</a></h3><ul><li>菜单行上 <strong><code>perms</code></strong> 汇总为权限字符串列表，供 <strong><code>getInfo</code></strong> 或全局鉴权使用（与现有 Sa-Token 用法衔接；若当前 <code>getInfo</code> 为占位，本迭代一并接好最小闭环）。</li></ul><h2 id="_7-前端设计" tabindex="-1">7. 前端设计 <a class="header-anchor vp-link" href="#_7-前端设计" aria-label="Permalink to &quot;7. 前端设计&quot;">​</a></h2><ul><li>实现前读取 <strong><code>DESIGN.md</code></strong> 与 <strong><code>sdd/前端代码规范.md</code></strong>。</li><li>页面：筛选（菜单名称、状态）、<code>el-table</code> 树表（展开/折叠）、操作列新增/修改/删除；表单含需求 §4 全部字段，<strong>按菜单类型切换显隐</strong>。</li><li>API：<code>quick-ui/src/api/system/menu.js</code>，与后端 POST 路径一致。</li><li>权限：<code>system:menu:list</code>、<code>system:menu:add</code>、<code>system:menu:edit</code>、<code>system:menu:remove</code>。</li><li><strong>路由入口</strong>：需保证首次登录后仍可通过种子菜单进入「菜单管理」页；若完全依赖动态路由，种子数据必须包含该页对应菜单与组件路径。</li></ul><h2 id="_8-验收标准-与原始需求-§7-对齐并细化" tabindex="-1">8. 验收标准（与原始需求 §7 对齐并细化） <a class="header-anchor vp-link" href="#_8-验收标准-与原始需求-§7-对齐并细化" aria-label="Permalink to &quot;8. 验收标准（与原始需求 §7 对齐并细化）&quot;">​</a></h2><ul><li>树结构与父子关系正确；筛选剪枝语义正确。</li><li>菜单类型切换后表单字段联动正确。</li><li>删除有子时拦截，<strong>提示明确</strong>。</li><li><code>getRouters</code> 非占位，侧边栏与动态路由与库中数据一致（在选定用户-角色绑定策略下）。</li><li><code>roleMenuTreeselect</code> 对有效 <code>roleId</code> 返回树与勾选 id。</li></ul><h2 id="_9-测试建议" tabindex="-1">9. 测试建议 <a class="header-anchor vp-link" href="#_9-测试建议" aria-label="Permalink to &quot;9. 测试建议&quot;">​</a></h2><ul><li>Service：建树、无参全树、名称/状态剪枝、删子拦截、改父成环。</li><li>可选：固定种子数据下 <code>getRouters</code> JSON 结构断言。</li></ul><h2 id="_10-开放式问题-已收口" tabindex="-1">10. 开放式问题（已收口） <a class="header-anchor vp-link" href="#_10-开放式问题-已收口" aria-label="Permalink to &quot;10. 开放式问题（已收口）&quot;">​</a></h2><ul><li><strong>用户与角色绑定</strong>：已采用 Flyway <strong><code>sys_user_role</code></strong> 种子（<code>user_id=1</code>、<code>role_id=1</code>）与占位登录 <code>StpUtil.login(1L)</code> 对齐；后续用户管理迭代改为真实用户-角色数据即可。</li></ul>',42)])])}const g=t(c,[["render",a]]);export{m as __pageData,g as default};
